// Small Talk annual course. Original teaching text; paired practice is deliberate.
const YEAR_UNITS=[];
function unit(title,en,pattern,grammar,vocab,scenes,mission,sound){YEAR_UNITS.push({title,en,pattern,grammar,vocab:vocab.split(';').map(s=>{let[en,zh,example]=s.split('|');return{en,zh,example}}),scenes:scenes.map(s=>({title:s[0],lines:s.slice(1)})),mission,sound});}
unit('第一次開口','First words',"I'm … / My name is …",'I am 可縮寫為 I’m。介紹姓名時用 My name is + 名字。英文句子以主詞開頭。',
`I|我|I am Alex.;you|你|You are Sam.;am|是（搭配 I）|I am new.;are|是（搭配 you）|You are welcome.;hello|你好|Hello, Sam.;name|名字|My name is Alex.;my|我的|my name;your|你的|your name;yes|是的|Yes, I am.;no|不是|No, I am not.;please|請|Sit down, please.;thanks|謝謝|Thanks for your help.;sorry|抱歉|Sorry, I am late.;welcome|歡迎|Welcome to Taiwan.;nice|令人愉快的|Nice to meet you.;meet|認識／見面|meet a friend;new|新的|I am new here.;here|這裡|I am here.;this|這個|This is Sam.;too|也|Nice to meet you, too.`,[
['交換姓名','Hello. My name is Alex.','Hi, Alex. I am Sam.','Nice to meet you, Sam.','Nice to meet you, too.'],
['確認身分','Are you Sam?','Yes, I am. Are you Alex?','Yes. I am new here.','Welcome, Alex.'],
['介紹新朋友','Sam, this is my friend, Jo.','Hello, Jo. Nice to meet you.','Hi, Sam. Nice to meet you, too.','Please sit here.']
],'不看提示，說出姓名、向對方問好，再介紹一位朋友。','先分清 I am 和 you are，再練習縮寫 I’m 與 you’re。');
unit('來自哪裡','Where we are from','I am from … / I live in …','from 表示來自哪裡；live in 表示目前居住地。問句用 Where are you from?，不要逐字照中文排序。',
`from|來自|I am from Taiwan.;live|居住|I live in Taipei.;in|在……裡|in Taiwan;city|城市|a big city;country|國家|my country;Taiwan|台灣|I am from Taiwan.;Taipei|台北|I live in Taipei.;Japan|日本|She is from Japan.;Canada|加拿大|He is from Canada.;English|英語|I speak English.;Chinese|中文|I speak Chinese.;speak|說（語言）|speak English;a little|一點點|a little English;where|哪裡|Where do you live?;what|什麼|What is your name?;and|和／而且|you and me;but|但是|small but nice;also|也|I also speak Chinese.;near|在……附近|near Taipei;now|現在|I live here now.`,[
['認識住處','Where are you from?','I am from Taiwan. How about you?','I am from Canada. Do you live in Taipei?','Yes. I live in Taipei now.'],
['談語言','Do you speak English?','A little. I also speak Chinese.','That is great. I speak a little Chinese.','We can practice together.'],
['介紹城市','Where do you live?','I live near Taipei. It is a big city.','Is your friend from Taiwan, too?','No. She is from Japan.']
],'用三句英文區分你的家鄉、現居地與會說的語言，再問對方一個問題。','live（居住）念短母音 /ɪ/；不要和 live music 的 live 混淆。');
unit('數字與聯絡方式','Numbers and contact details','How many …? / My number is …','問數量用 How many + 複數名詞。電話號碼通常一個數字一個數字讀。',
`one|一|one book;two|二|two cups;three|三|three days;four|四|four people;five|五|five minutes;six|六|six chairs;seven|七|seven days;eight|八|eight hours;nine|九|nine o'clock;ten|十|ten dollars;zero|零|zero nine;number|號碼|my phone number;phone|電話|my phone;email|電子郵件|my email address;address|地址|your address;spell|拼字|How do you spell it?;letter|字母|the first letter;again|再一次|Say it again.;slowly|慢慢地|Speak slowly, please.;correct|正確的|That is correct.`,[
['確認數量','How many people are coming?','Three people. Do we have four chairs?','Yes. We have four chairs.','Great. We need one more cup.'],
['拼姓名','How do you spell your name?','S, A, M.','Can you say it again, slowly?','Sure. S, A, M.'],
['交換電話','What is your phone number?','It is zero nine, one two, three four.','Zero nine, one two, three four. Is that correct?','Yes, that is correct.']
],'用虛構資料練習拼姓名與報電話，不要在公開筆記填真實聯絡資料。','three 的 th 舌尖輕放上下齒之間；不要讀成 tree。');
unit('人與基本句子','People and simple sentences','He is … / She is … / They are …','he、she、it 配 is；we、they 配 are。be 動詞否定句在後面加 not。',
`he|他|He is my friend.;she|她|She is a teacher.;we|我們|We are ready.;they|他們|They are here.;it|它|It is small.;is|是（第三人稱單數）|It is good.;not|不／不是|I am not tired.;friend|朋友|a good friend;person|人|one person;people|人們|three people;teacher|老師|an English teacher;student|學生|I am a student.;man|男人|that man;woman|女人|that woman;child|孩子|a happy child;adult|成年人|two adults;good|好的|a good day;kind|親切的|She is kind.;ready|準備好的|We are ready.;together|一起|We study together.`,[
['介紹身分','Is she your teacher?','No, she is my friend.','Is she a student?','Yes. We study English together.'],
['確認準備','Are they ready?','They are not ready yet.','Are you ready?','Yes. I am ready now.'],
['認識一群人','Who are those people?','They are my friends.','Are they kind?','Yes. They are very kind.']
],'介紹三個不同的人，至少用一次 he、she、they，以及一句否定句。','縮寫 he’s、she’s、it’s 的尾音要保留，但不必額外加一個母音。');
unit('一天的作息','Daily routines','I usually … / Do you …?','一般現在式描述習慣。問 you 的習慣時用 Do you + 動詞原形；回答 Yes, I do. 或 No, I don’t.。',
`wake up|醒來|I wake up at seven.;get up|起床|I get up early.;eat|吃|eat breakfast;drink|喝|drink water;breakfast|早餐|have breakfast;lunch|午餐|eat lunch;dinner|晚餐|cook dinner;go|去|go home;come|來|come here;leave|離開|leave home;start|開始|start work;finish|完成／結束|finish work;sleep|睡覺|sleep well;usually|通常|I usually walk.;every day|每天|practice every day;early|早的／早地|get up early;late|晚的／遲到的|I am late.;after|在……之後|after work;before|在……之前|before breakfast;at|在（時間點）|at seven.`,[
['早晨習慣','What do you do in the morning?','I eat breakfast and go to work.','Do you drink coffee?','Yes, I do. I drink it after breakfast.'],
['下班時間','What time do you finish work?','I usually finish at six.','Do you go home after work?','Yes. I cook dinner at home.'],
['睡前習慣','Do you go to bed early?','No, I do not. I usually sleep late.','Do you study before bed?','Yes. I study English for ten minutes.']
],'照時間順序介紹你一天的四個動作，再問對方是否也這樣做。','do you 可以自然連起來，但初期先清楚說出兩個字。');
unit('時間與一週安排','Time and the week','What time …? / On Monday, I …','星期前面用 on；明確鐘點前用 at。描述固定安排可用一般現在式。',
`time|時間|What time is it?;hour|小時|one hour;minute|分鐘|five minutes;today|今天|Today is Monday.;tomorrow|明天|See you tomorrow.;yesterday|昨天|yesterday morning;Monday|星期一|on Monday;Tuesday|星期二|on Tuesday;Wednesday|星期三|on Wednesday;Thursday|星期四|on Thursday;Friday|星期五|on Friday;Saturday|星期六|on Saturday;Sunday|星期日|on Sunday;week|星期／週|this week;weekend|週末|on the weekend;morning|早上|in the morning;afternoon|下午|this afternoon;evening|傍晚／晚上|in the evening;night|夜晚|at night;half|一半|half an hour.`,[
['約定鐘點','What time is the class?','It starts at nine on Monday.','Is it one hour long?','Yes. It finishes at ten.'],
['平日與週末','Do you work on Saturday?','No. I work from Monday to Friday.','What do you do on Sunday?','I visit a friend in the afternoon.'],
['確認日期','Is the meeting today?','No. It is tomorrow morning.','What time does it start?','At ten. Please come five minutes early.']
],'用英文安排本週三件事，說出星期、時間與活動。','聽辨 thirteen 和 thirty 類數字時留意重音；不要只猜最後的音。');
unit('家人與關係','Family and relationships','I have … / Do you have …?','have 表示擁有或家庭關係。單數可數名詞前常需要 a 或 an；複數則依情況加 s。',
`family|家人／家庭|my family;mother|母親|my mother;father|父親|my father;parent|父母之一|my parents;sister|姊妹|one sister;brother|兄弟|my brother;wife|妻子|his wife;husband|丈夫|her husband;daughter|女兒|their daughter;son|兒子|her son;grandmother|祖母／外祖母|my grandmother;grandfather|祖父／外祖父|my grandfather;cousin|堂／表兄弟姊妹|my cousin;have|有|I have a brother.;has|有（第三人稱單數）|She has a sister.;a|一個|a brother;an|一個（母音音素前）|an adult;our|我們的|our family;their|他們的|their parents;visit|探訪|visit my family.`,[
['介紹手足','Do you have any brothers or sisters?','I have one sister.','Does she live near you?','Yes. We often have dinner together.'],
['週末探親','Who do you visit on Sunday?','I visit my grandparents.','Do they live in Taipei?','No. They live in a small town.'],
['介紹家人','Is this your family?','Yes. This is my mother and this is my brother.','Does your brother have children?','Yes. He has a daughter.']
],'畫簡單關係圖，用英文介紹四位家人或虛構人物。','parents 的尾音 /ts/ 可以輕輕帶出，不要在後面多加一個字。');
unit('家與日常物品','Home and everyday objects','There is … / There are …','There is 搭配單數；There are 搭配複數，用來介紹某處有什麼。',
`home|家|at home;house|房屋|a small house;apartment|公寓|my apartment;room|房間|a quiet room;kitchen|廚房|in the kitchen;bathroom|浴室|the bathroom;bedroom|臥室|my bedroom;door|門|open the door;window|窗戶|near the window;table|桌子|on the table;chair|椅子|a wooden chair;bed|床|a comfortable bed;sofa|沙發|on the sofa;key|鑰匙|my keys;bag|袋子／包包|a black bag;book|書|an English book;on|在……上面|on the desk;under|在……下面|under the chair;next to|在……旁邊|next to the bed;between|在……之間|between two chairs.`,[
['介紹住家','Is your apartment big?','No. There is one bedroom and a small kitchen.','Is there a window in your bedroom?','Yes. My bed is next to it.'],
['找物品','Where are my keys?','They are on the table.','Are they next to my bag?','No. They are under your book.'],
['招待朋友','Please sit on the sofa.','Thanks. Your room is nice.','Would you like some water?','Yes, please. A little water is fine.']
],'環顧房間，直接用英文描述五個物品的位置，不先寫中文。','there is 和 there are 可連讀，先確認單複數再加快速度。');
unit('食物與口味','Food and taste','I like … / I do not like …','談一般喜好時，食物常用不可數形式或複數：I like rice. / I like apples.。',
`food|食物|good food;rice|米飯|a bowl of rice;bread|麵包|some bread;noodle|麵條|a bowl of noodles;egg|蛋|two eggs;chicken|雞肉|grilled chicken;fish|魚／魚肉|fresh fish;vegetable|蔬菜|green vegetables;fruit|水果|fresh fruit;apple|蘋果|an apple;banana|香蕉|a banana;milk|牛奶|some milk;tea|茶|hot tea;coffee|咖啡|a cup of coffee;water|水|drink water;sweet|甜的|too sweet;salty|鹹的|a little salty;spicy|辣的|spicy noodles;fresh|新鮮的|fresh vegetables;hungry|餓的|I am hungry.`,[
['分享喜好','What food do you like?','I like noodles and vegetables.','Do you like spicy food?','Yes, but not too spicy.'],
['談早餐','What do you eat for breakfast?','I usually have bread and an egg.','Do you drink milk?','No. I usually drink tea.'],
['描述口味','How is the soup?','It is a little salty.','Would you like some water?','Yes, please. I am thirsty.']
],'描述今天一餐的食物、口味與喜好，再推薦一道菜。','vegetable 常見讀法的音節會縮短，跟著例句聽，不必每個字母都念。');
unit('咖啡店與餐廳','Ordering politely','I would like … / Could I have …?','I would like 比 I want 更適合禮貌點餐。a coffee 可表示一杯咖啡；some water 表示一些水。',
`menu|菜單|the menu;order|點餐|ready to order;bill|帳單|the bill;cup|杯子|a cup of tea;glass|玻璃杯／一杯|a glass of water;bowl|碗|a bowl of soup;plate|盤子|a clean plate;fork|叉子|a fork;spoon|湯匙|a spoon;knife|刀子|a knife;soup|湯|hot soup;salad|沙拉|a fresh salad;sandwich|三明治|a chicken sandwich;hot|熱的|hot coffee;cold|冷的|cold water;ice|冰塊|without ice;sugar|糖|no sugar;without|沒有／不加|without milk;takeout|外帶食物|takeout coffee;anything else|還要別的嗎|Anything else?`,[
['點一杯飲料','What would you like?','I would like a hot tea, please.','Would you like sugar?','No sugar, thank you.'],
['詢問餐點','Are you ready to order?','Yes. Could I have the chicken sandwich?','Would you like soup with that?','Yes, please.'],
['結帳與外帶','Could I have the bill, please?','Of course. Anything else?','Could I take this sandwich with me?','Sure. I can put it in a bag.']
],'完整模擬入座、點餐、調整口味及結帳；每次更換餐點。','would like 裡的 d 常不明顯；先聽完整語塊，而不是逐字翻譯。');
unit('購物與價格','Shopping and prices','How much is …? / Can I try …?','問單件商品價格用 How much is it?；複數用 How much are they?。',
`shop|商店|a small shop;store|商店|a clothing store;price|價格|a good price;cost|花費|How much does it cost?;dollar|元|ten dollars;cheap|便宜的|a cheap bag;expensive|昂貴的|too expensive;buy|買|buy a shirt;pay|付款|pay by card;cash|現金|pay in cash;card|卡片／卡|a credit card;receipt|收據|keep the receipt;size|尺寸|a small size;color|顏色|my favorite color;black|黑色的|a black shirt;white|白色的|white shoes;blue|藍色的|a blue bag;red|紅色的|a red cup;try on|試穿|try on this shirt;fit|合身|It fits well.`,[
['詢問價格','How much is this bag?','It is twenty dollars.','Do you have a cheaper one?','Yes. This blue one is ten dollars.'],
['試穿尺寸','Can I try on this shirt?','Of course. What size do you need?','A small size, please.','Here you are.'],
['結帳付款','Can I pay by card?','Yes, you can.','Could I have a receipt?','Certainly. Here is your receipt.']
],'用不同價格與尺寸買一件衣服，至少問兩個實際問題。','receipt 的 p 不發音；price 的尾音是 /s/，不是 /z/。');
unit('搭車與通勤','Getting around','I take … / How do I get to …?','交通方式可用 take the bus / train；走路用 walk，不需要 take。',
`bus|公車|take the bus;train|火車|a fast train;subway|地鐵|take the subway;taxi|計程車|take a taxi;car|汽車|drive a car;bike|腳踏車|ride a bike;walk|走路|walk to work;ride|騎乘|ride a bike;drive|開車|drive to work;station|車站|the train station;stop|站牌／停止|the bus stop;ticket|票|a train ticket;platform|月台|platform two;line|路線|the red line;change|轉乘／改變|change trains;arrive|抵達|arrive at nine;wait|等待|wait for the bus;fast|快的|a fast train;slow|慢的|a slow bus;far|遠的|far from here.`,[
['介紹通勤','How do you get to work?','I take the subway.','Is the station near your home?','Yes. It is a five-minute walk.'],
['買車票','One ticket to Taipei, please.','The next train leaves at ten.','Which platform do I need?','Platform two.'],
['搭公車','Does this bus go to the station?','Yes, it does.','Where should I get off?','At the third stop.']
],'模擬問路、買票和確認下車站，最後介紹你的通勤方式。','train 和 change 的尾音不同；放進完整句子練習，不只重複單字。');
unit('三個月對話整合','Your first conversations','Could you repeat that? / Let me try again.','沒聽懂時可以請求重複、放慢或換說法。這是溝通能力的一部分。',
`repeat|重複|Could you repeat that?;understand|理解|I understand.;mean|意思是|What does it mean?;practice|練習|practice speaking;question|問題|ask a question;answer|回答／答案|a short answer;ask|詢問|ask for help;tell|告訴|tell me;say|說出|say it slowly;listen|聽|listen carefully;hear|聽見|I can hear you.;read|閱讀|read a book;write|寫|write your name;help|幫助|help me;try|嘗試|try again;remember|記得|remember a name;forget|忘記|forget a word;easy|容易的|an easy question;difficult|困難的|a difficult word;a bit|一點點|a bit slower.`,[
['請對方重複','Where do you usually go on weekends?','Sorry, could you repeat that?','What do you do on Saturday and Sunday?','I visit my family and eat with friends.'],
['主動修正','I live from Taipei. Sorry, let me try again.','Take your time.','I live in Taipei. I am from Tainan.','I understand. Thanks for explaining.'],
['延伸簡單聊天','What do you like about your city?','I like the food. There are many small restaurants.','What food do you recommend?','Try the noodles near the station.']
],'進行三分鐘自我介紹與生活對話，使用至少一次澄清問句，回聽後記下兩個可改善處。','請求重複時用平穩語調；慢一點說清楚，比勉強加速更有幫助。');
unit('方向與城市生活','Finding your way','Go straight … / It is across from …','用祈使句給方向時，直接以動詞開頭：Turn left.。位置和移動要分開描述。',
`left|左邊|turn left;right|右邊|turn right;straight|直直地|go straight;corner|轉角|at the corner;street|街道|a quiet street;road|道路|cross the road;cross|穿越|cross the street;across from|在……對面|across from the bank;behind|在……後面|behind the station;in front of|在……前面|in front of the shop;bank|銀行|near the bank;park|公園|walk in the park;library|圖書館|the public library;museum|博物館|visit a museum;supermarket|超級市場|go to the supermarket;entrance|入口|the main entrance;exit|出口|use this exit;map|地圖|check the map;block|街區|two blocks away;around|在……周圍／轉過|around the corner.`,[
['問圖書館在哪','Excuse me. Where is the library?','Go straight for two blocks, then turn left.','Is it across from the bank?','Yes. The entrance is on your right.'],
['確認方向','Should I turn here?','Not yet. Turn right at the next corner.','Is the museum behind the park?','Yes. It is next to the station exit.'],
['說明附近環境','Is there a supermarket near your home?','Yes. It is around the corner.','Can we walk there?','Sure. It takes about five minutes.']
],'畫一張簡單地圖，從車站帶對方走到三個不同地方。','right 的 r 和 light 的 l 要區分；使用 turn right 的整段音檔練習。');
unit('天氣與穿著','Weather and clothing','It is … / You should bring …','談天氣常以 It 開頭：It is raining.。不要把中文的「今天」直接當英文句子的主詞。',
`weather|天氣|the weather today;sunny|晴朗的|a sunny day;rainy|下雨的|a rainy morning;cloudy|多雲的|cloudy weather;windy|有風的|a windy afternoon;warm|溫暖的|warm weather;cool|涼爽的|a cool evening;cold|寒冷的|a cold night;rain|下雨／雨|heavy rain;snow|雪／下雪|white snow;umbrella|雨傘|bring an umbrella;jacket|外套|wear a jacket;coat|大衣|a warm coat;shirt|襯衫／上衣|a clean shirt;pants|長褲|black pants;shoes|鞋子|comfortable shoes;wear|穿戴|wear a hat;bring|帶來|bring a jacket;season|季節|my favorite season;temperature|溫度|a high temperature.`,[
['出門前聊天','What is the weather like today?','It is cloudy and a little cool.','Should I bring a jacket?','Yes. It may rain this evening.'],
['談季節','What is your favorite season?','I like spring because it is warm.','Does it rain a lot in Taiwan?','Yes, especially in summer.'],
['調整計畫','Do you want to walk to the park?','It is raining. I do not have an umbrella.','We can go to a cafe instead.','Good idea. Let me get my jacket.']
],'根據三種天氣安排活動和穿著，並說明一個原因。','weather 的 th 帶有聲音，和 three 的 th 不同；先聽示範再模仿。');
unit('興趣與休閒','Hobbies and free time','I enjoy … / How often do you …?','enjoy 後面常接動名詞：enjoy reading。頻率副詞 usually、often 通常放在一般動詞前。',
`hobby|嗜好|my hobby;free time|空閒時間|in my free time;music|音樂|listen to music;movie|電影|watch a movie;film|電影|a funny film;song|歌曲|my favorite song;sing|唱歌|sing a song;dance|跳舞|learn to dance;swim|游泳|swim in a pool;run|跑步|run in the park;hike|健行|hike in the mountains;cook|烹飪|cook at home;draw|畫圖|draw a picture;game|遊戲|play a game;play|玩／演奏|play the guitar;enjoy|享受／喜歡|enjoy reading;often|經常|I often walk.;sometimes|有時候|I sometimes cook.;never|從不|I never smoke.;once|一次|once a week.`,[
['分享興趣','What do you do in your free time?','I enjoy cooking and watching movies.','What kind of movies do you like?','I like funny movies. They help me relax.'],
['談運動頻率','How often do you go hiking?','About once a month.','Do you usually go alone?','No. I go with two friends.'],
['找共同興趣','Do you play any games?','Sometimes. I prefer games I can play with friends.','Would you like to try this one?','Sure. Can you show me how to play?']
],'談一個興趣兩分鐘，加入頻率、原因、同伴和追問。','enjoy 的重音在後面；watch 的尾音要收住，不必加上「奇」的母音。');
unit('喜好與選擇','Preferences and choices','I prefer … to … / I would rather …','prefer A to B 表達相對偏好。先給選擇，再用 because 解釋一個具體理由。',
`prefer|偏好|I prefer tea.;favorite|最喜愛的|my favorite place;choose|選擇|choose a seat;choice|選擇／選項|a good choice;option|選項|another option;both|兩者都|both options;either|兩者任一|either day;neither|兩者都不|neither option;instead|改為／代替|walk instead;reason|原因|the main reason;because|因為|because it is quiet;quiet|安靜的|a quiet cafe;loud|大聲的|loud music;comfortable|舒適的|a comfortable chair;simple|簡單的|a simple meal;popular|受歡迎的|a popular restaurant;different|不同的|a different idea;same|相同的|the same size;really|真的／很|I really like it.;rather|寧願（搭配 would）|I would rather stay.`,[
['選咖啡店','Would you prefer a quiet cafe or a busy one?','A quiet one. I want to talk.','This cafe has comfortable seats.','Then let us try it.'],
['選活動','Would you rather watch a movie or go for a walk?','I would rather walk. The weather is nice.','Should we go to the park?','Yes. That sounds good.'],
['比較喜好','Do you prefer tea to coffee?','Yes. Coffee sometimes keeps me awake.','What is your favorite kind of tea?','I like simple green tea without sugar.']
],'在兩組選項中做選擇，每次給不同理由，並回應對方不同的喜好。','prefer 的重音在第二音節；because 可輕讀，把重點留給後面的理由。');
unit('身體與感受','Talking about how you feel','I feel … / I have a …','描述感受常用 feel + 形容詞；描述身體不適可用 have + 名詞。課程只練表達，不提供醫療判斷。',
`feel|感覺|I feel tired.;tired|疲倦的|a little tired;sick|不舒服的|I feel sick.;well|健康的／好地|I do not feel well.;better|更好的|I feel better.;head|頭|my head;stomach|胃／腹部|my stomach;back|背部|my back;hand|手|wash your hands;foot|腳|my left foot;pain|疼痛|back pain;headache|頭痛|have a headache;rest|休息|take a rest;water bottle|水瓶|fill a water bottle;healthy|健康的|a healthy meal;exercise|運動|regular exercise;stress|壓力|work stress;break|休息時間|take a break;energy|精力|more energy;care|照顧／在乎|take care.`,[
['關心朋友','You look tired. Are you okay?','I did not sleep well last night.','Would you like to take a break?','Yes. A short break would help.'],
['說明狀況','How are you feeling today?','A little better, but I still have a headache.','Do you need to go home?','I think I need some rest.'],
['談健康習慣','What helps you relax after work?','A short walk and a good meal.','Do you exercise every day?','Not every day, but I try to move more.']
],'用英文說明一個日常感受、需要的協助，以及你常用的放鬆方法。','feel 的長母音和 fill 的短母音不同；把 I feel better 當成一個語塊。');
unit('預約與時間協調','Appointments','I would like to make an appointment.','用 available 詢問有空時段。確認日期、鐘點和地點能避免只聽懂一部分。',
`appointment|預約|make an appointment;available|有空的|available on Friday;booking|預訂|confirm a booking;confirm|確認|confirm the time;cancel|取消|cancel an appointment;reschedule|改期|reschedule the meeting;calendar|行事曆|check my calendar;date|日期|the correct date;month|月份|next month;next|下一個|next Tuesday;last|上一個／最後的|last week;open|營業中的／打開|The shop is open.;closed|關閉的|The office is closed.;full|額滿的／滿的|The schedule is full.;free|有空的／免費的|Are you free?;busy|忙碌的|a busy afternoon;morning slot|早上時段|a morning slot;on time|準時|arrive on time;at least|至少|at least ten minutes;change of plan|計畫變動|a change of plan.`,[
['提出預約','I would like to make an appointment.','Are you available on Tuesday morning?','Yes. What time can I come?','We have a slot at ten thirty.'],
['預約改期','Could I reschedule my appointment?','Of course. Is Friday afternoon okay?','Yes. Could we make it three o’clock?','Certainly. I will confirm the change.'],
['確認細節','I am calling to confirm my booking.','It is for next Monday at nine.','Should I arrive early?','Please come at least ten minutes before your appointment.']
],'模擬預約、改期和確認，最後複述日期、時間與地點。','-teen 和 -ty 要分清；確認時完整重述數字，不只說 okay。');
unit('工作與職責','Work and responsibilities','I work as … / My job involves …','職稱前常用 a/an：I am a designer.。work as 說職務，work for 說雇主，work in 說領域或地方。',
`job|工作職位|a new job;work|工作|work in a shop;office|辦公室|at the office;company|公司|a small company;team|團隊|our team;coworker|同事|my coworker;manager|經理|the store manager;customer|顧客|help a customer;client|客戶|meet a client;staff|員工群體|the office staff;designer|設計師|a web designer;technician|技術人員|a repair technician;service|服務|customer service;task|任務|finish a task;project|專案|a small project;responsible|負責的|responsible for bookings;handle|處理|handle questions;support|支援|support the team;part-time|兼職的|a part-time job;full-time|全職的|work full-time.`,[
['介紹工作','What do you do?','I work as a technician in a small shop.','What does your job involve?','I help customers and repair devices.'],
['認識同事','Is Jo your manager?','No. Jo is a designer on my team.','What are you responsible for?','I handle customer questions and bookings.'],
['比較工作日','Do you work full-time?','Yes, from Monday to Friday.','What is the busiest part of your day?','The afternoon, when many customers come in.']
],'用一分鐘介紹工作、兩項職責和一天最忙的時段；沒有工作可使用虛構角色。','work 和 walk 的母音不同；不要靠中文注音記發音。');
unit('訊息與電子郵件','Messages and email','Could you send …? / Just to confirm …','工作訊息先說目的，再說需要對方做什麼，最後交代時間。短句通常比一長串翻譯句清楚。',
`message|訊息|send a message;send|寄送|send an email;receive|收到|receive a reply;reply|回覆|reply to a message;attachment|附件|check the attachment;file|檔案|open a file;document|文件|share a document;subject|主旨|the email subject;detail|細節|confirm the details;update|更新|a quick update;information|資訊|useful information;contact|聯絡|contact the office;forward|轉寄|forward the email;check|確認／檢查|check your inbox;inbox|收件匣|in my inbox;link|連結|send a link;by Friday|週五之前|finish by Friday;as soon as|一……就|reply as soon as possible;let me know|讓我知道|Please let me know.;just to confirm|只是想確認|Just to confirm the time.`,[
['確認收件','Did you receive my email?','Yes, but I cannot open the attachment.','I will send the file again.','Thanks. Please send it as a link this time.'],
['簡短更新','Do you have an update on the project?','The first draft is ready. I sent it this morning.','Could you forward it to Jo?','Sure. I will do that now.'],
['確認需求','Just to confirm, do you need the document by Friday?','Yes. A short summary is enough.','Should I include the price details?','Yes, please. Let me know if you have questions.']
],'寫一則四句英文訊息：目的、所需行動、期限、禮貌結尾，再大聲讀出來。','send 的 d 要和 sent 的 t 區分；聽不清楚時用日期或上下文確認。');
unit('禮貌請求與協助','Requests and offers','Could you …? / Would you like me to …?','Could you + 動詞原形用來請人協助；Would you like me to + 動詞是主動提出幫忙。',
`could|可以（禮貌請求）|Could you help?;would|會／願意（助動詞）|Would you like help?;lend|借給|lend me a pen;borrow|借入|borrow a charger;show|展示／帶著看|show me the way;explain|解釋|explain the problem;carry|搬／提|carry a bag;hold|拿著／稍候|hold the door;move|移動|move this chair;share|分享|share your screen;need|需要|need some help;offer|提供／提議|offer some help;favor|幫忙的事|ask a favor;possible|可能的|Is it possible?;minute please|請稍等一下|One minute, please.;no problem|沒問題|No problem.;of course|當然|Of course I can.;certainly|當然可以|Certainly.;not yet|還沒|Not yet.;in a moment|稍後片刻|I will help in a moment.`,[
['借物品','Could I borrow your charger?','Of course. Here you are.','Thanks. I will give it back after lunch.','No problem. I do not need it now.'],
['提出幫忙','That bag looks heavy. Would you like me to carry it?','Yes, please. That would be helpful.','Where should I put it?','Next to the door, please.'],
['請人說明','Could you explain this step again?','Certainly. First, open the file.','Should I click this button next?','Yes. Let me show you.']
],'練習請求、接受與婉拒協助；每次加入一個具體動作或物品。','could 和 would 裡的 l 不發音；請求語氣可以柔和，不必每句都上揚。');
unit('昨天做了什麼','Past routines','I worked … / Did you …?','一般過去式描述已結束的事情。did 問句後用原形：Did you work?，不是 Did you worked?。',
`worked|工作了|I worked yesterday.;studied|讀書了|I studied English.;watched|看了|I watched a film.;played|玩了／演奏了|I played a game.;cleaned|清理了|I cleaned my room.;cooked|煮了|I cooked dinner.;walked|走了|I walked home.;called|打電話了|I called Sam.;helped|幫忙了|I helped a friend.;needed|需要了|I needed a break.;wanted|想要了|I wanted some tea.;started|開始了|The class started.;finished|結束了|I finished at six.;stayed|待了|I stayed home.;visited|探訪了|I visited my aunt.;did|做了／過去式助動詞|Did you work?;ago|以前|two days ago;last night|昨晚|last night;then|然後／那時|and then;until|直到|until nine.`,[
['昨晚的活動','What did you do last night?','I cooked dinner and watched a movie.','Did you study English, too?','Yes. I studied for twenty minutes.'],
['昨天的工作','Did you work yesterday?','Yes. I started early and finished at five.','What did you do after work?','I walked home and called a friend.'],
['週末整理','How was your Saturday?','Quiet. I stayed home and cleaned my room.','Did anyone help you?','No. But I finished everything before dinner.']
],'用四句話回顧昨天，加入時間詞，再問對方兩個過去式問題。','-ed 有 /t/、/d/、/ɪd/ 等讀法；比較 watched、played、wanted 的音檔。');
unit('過去的經驗動詞','Past events','I went … / I did not …','常用不規則過去式需要在情境中熟悉；否定句 did not 後仍用原形。',
`went|去了|I went to Taipei.;came|來了|She came early.;saw|看見了|I saw a friend.;met|見面了|We met at noon.;ate|吃了|I ate noodles.;drank|喝了|I drank tea.;bought|買了|I bought a book.;took|搭乘了／拿了|I took the bus.;made|製作了|I made dinner.;got|得到／抵達了|I got home late.;had|有／吃過了|I had lunch.;was|是（過去式單數）|It was fun.;were|是（過去式複數）|They were kind.;felt|感覺到（過去式）|I felt tired.;found|找到了|I found my keys.;lost|遺失了|I lost my ticket.;gave|給了|She gave me a book.;told|告訴了|He told me a story.;brought|帶來了|I brought some food.;left|離開了|We left at six.`,[
['回顧出遊','Where did you go yesterday?','I went to a small town near the sea.','What did you eat there?','I had fresh fish and rice.'],
['偶遇朋友','I saw Jo at the station.','Did you talk to her?','Yes. We had coffee together.','That sounds nice.'],
['處理小意外','Why were you late?','I lost my ticket and took the next train.','Did you find the ticket later?','Yes. It was in my jacket pocket.']
],'分享一次出門的經驗，用五個過去式動詞串成短故事。','bought 和 brought 的 r 有差別；先模仿整句 I bought a book。');
unit('把週末說成故事','Weekend stories','First …, then …, finally …','故事先交代何時、在哪裡、和誰，再按順序描述事件，最後說感受。',
`story|故事|tell a story;first|首先|First, we had lunch.;next step|下一步|the next step;finally|最後|Finally, we went home.;during|在……期間|during the trip;while|當……時／同時|while we waited;suddenly|突然|It suddenly rained.;luckily|幸運地|Luckily, we had an umbrella.;unfortunately|不幸地|Unfortunately, the shop was closed.;surprised|驚訝的|I was surprised.;excited|興奮的|We were excited.;boring|無聊的|a boring film;funny|好笑的|a funny story;memorable|難忘的|a memorable day;event|活動／事件|a local event;happened|發生了|What happened?;decided|決定了|We decided to walk.;ended|結束了|The trip ended well.;spent|花費了|We spent an hour there.;enough|足夠的|enough time.`,[
['分享行程','How was your weekend?','Great. First, we visited a museum. Then we had lunch nearby.','What did you do after lunch?','We walked by the river and finally took the train home.'],
['故事中的意外','Did everything go as planned?','Not really. It suddenly started to rain.','What did you do?','Luckily, we found a cafe and waited there.'],
['回應故事','What was the best part of the day?','We met an old friend by chance.','Were you surprised?','Very. We spent an hour talking about school.']
],'說一段兩分鐘故事，包含開頭、事件、意外或轉折、感受與結尾。','故事中的 first、then、finally 可稍停頓，讓聽者跟得上順序。');
unit('旅行與行程','Planning a trip','We are going to … / How long …?','be going to 表達計畫。How long 問持續多久；How far 問距離。',
`travel|旅行|travel by train;trip|旅行行程|a short trip;journey|旅程|a long journey;holiday|假期|a summer holiday;vacation|休假／假期|take a vacation;plan|計畫|make a plan;destination|目的地|our destination;route|路線|a scenic route;guide|導覽員／指南|a local guide;tour|導覽行程|a walking tour;pack|打包|pack a bag;luggage|行李|light luggage;suitcase|行李箱|one suitcase;backpack|背包|a small backpack;passport|護照|check your passport;reservation|預訂|a hotel reservation;budget|預算|a small budget;local|當地的|local food;abroad|在國外|travel abroad;stay|停留／住宿|stay for three nights.`,[
['討論目的地','Where are you going for your vacation?','We are going to Japan.','How long are you going to stay?','About a week. We want to try local food.'],
['規劃行程','Have you planned your route?','Yes. First, we will stay in the city for two nights.','What happens after that?','We are going to take a train to a small town.'],
['準備出發','Are you ready for the trip?','Almost. I still need to pack my bag.','Do you have your passport and reservation details?','Yes. I checked them this morning.']
],'用英文規劃三天旅行，說明目的地、交通、住宿、活動與預算取捨。','luggage 是不可數名詞；聽到 a piece of luggage 時抓住整個語塊。');
unit('飯店與住宿需求','At the hotel','I have a reservation under …','under + 姓名可用於查預訂。提出住宿需求時先說問題，再提出具體請求。',
`reception|接待處|at reception;check in|辦理入住|check in at three;check out|辦理退房|check out tomorrow;single room|單人房|a single room;double room|雙人房|a double room;floor|樓層|the third floor;elevator|電梯|take the elevator;stairs|樓梯|use the stairs;key card|房卡|my key card;towel|毛巾|a clean towel;blanket|毯子|an extra blanket;pillow|枕頭|a soft pillow;shower|淋浴|a hot shower;air conditioning|空調|the air conditioning;working|運作正常的|It is not working.;extra|額外的|an extra towel;included|包含的|Breakfast is included.;per night|每晚|fifty dollars per night;quiet room|安靜的房間|a quiet room;under the name|以……姓名登記|under the name Lee.`,[
['辦理入住','Hello. I have a reservation under the name Lee.','Welcome. You booked a double room for two nights.','Is breakfast included?','Yes. It is served on the second floor.'],
['提出房間問題','The air conditioning in my room is not working.','I am sorry about that. What is your room number?','Room three twelve. Could someone check it?','Certainly. We will send someone up.'],
['退房與寄物','I would like to check out.','Of course. Did you enjoy your stay?','Yes, thank you. Could I leave my bag here until three?','Certainly. We can keep it at reception.']
],'模擬入住、反映一個問題和退房寄物，確認每個請求得到回應。','room 和 floor 的母音不同；房號可一個數字一個數字說清楚。');
unit('機場與出入境對話','At the airport','Where can I …? / My flight has …','用 Where can I + 動詞詢問服務地點。遇到異動時，確認新時間、登機門和後續動作。',
`airport|機場|at the airport;flight|航班|my flight;airline|航空公司|a local airline;gate|登機門|gate twelve;boarding pass|登機證|show your boarding pass;boarding|登機|Boarding starts at eight.;departure|出發|the departure time;arrival|抵達|the arrival hall;delayed|延誤的|The flight is delayed.;canceled|被取消的|a canceled flight;security|安全檢查／保全|go through security;customs|海關|go through customs;baggage claim|行李領取處|at baggage claim;carry-on|隨身行李|one carry-on bag;aisle seat|走道座位|an aisle seat;window seat|靠窗座位|a window seat;connection|轉機班次|miss a connection;terminal|航廈|terminal two;departure board|航班資訊看板|check the departure board;passport control|護照查驗|go to passport control.`,[
['機場報到','Could I have a window seat?','Let me check. Yes, there is one available.','Do I need to check this bag?','No. It is small enough for carry-on luggage.'],
['班機延誤','Has the boarding time changed?','Yes. Your flight is delayed by one hour.','Is the gate still the same?','Yes. Please check the departure board for updates.'],
['領取行李','Excuse me. Where is baggage claim?','Follow the signs and go down one floor.','Do I go through passport control first?','Yes. Baggage claim is after passport control.']
],'模擬從報到到領行李的三段對話，遇到不確定資訊時主動複述確認。','boarding 和 baggage 的起首重音要聽清楚，不必用中文音譯背誦。');
unit('服務問題與退換貨','Service problems','There seems to be … / Could I get …?','先描述可觀察的問題，再說希望的處理方式。禮貌不代表只說 sorry 而不說清楚需求。',
`problem|問題|a small problem;issue|待處理的問題|a delivery issue;broken|壞掉的|a broken screen;damaged|受損的|a damaged box;missing|缺少的|a missing part;wrong|錯誤的|the wrong size;return|退回／退貨|return an item;exchange|交換／換貨|exchange this shirt;refund|退款|ask for a refund;replace|更換|replace the cable;repair|修理|repair the device;warranty|保固|under warranty;policy|規定／政策|the return policy;proof|證明|proof of purchase;purchase|購買|a recent purchase;delivery|配送|a late delivery;package|包裹|open the package;solution|解決辦法|find a solution;resolve|解決|resolve the issue;apologize|道歉|I apologize for the delay.`,[
['商品有問題','I bought this yesterday, but it does not turn on.','Do you have the receipt?','Yes. Could I exchange it?','Of course. We can replace it with a new one.'],
['詢問退貨','This shirt is the wrong size. Can I return it?','Yes, if you have proof of purchase.','Could I get a refund instead of an exchange?','Let me check our return policy.'],
['包裹缺件','There seems to be a missing part in my package.','I am sorry. Which part is missing?','The charging cable.','We can send a replacement cable today.']
],'用「何時買、什麼問題、希望怎麼處理」三部分提出服務請求。','issue 和 exchange 不要逐字母念；聽範例中的重音位置。');
unit('未來安排與承諾','Plans and promises','I am going to … / I will …','going to 常用於已有計畫；will 也可用於當下決定或承諾。不要把所有未來句都機械地加 will。',
`future|未來|in the future;goal|目標|a learning goal;going to|打算|I am going to study.;will|將會／願意|I will help.;soon|很快|see you soon;later|稍後|call you later;tonight|今晚|tonight after dinner;next year|明年|travel next year;intend|打算|intend to apply;hope|希望|hope to improve;expect|預期|expect a reply;promise|承諾|keep a promise;prepare|準備|prepare for a trip;arrange|安排|arrange a meeting;decide|決定|decide tomorrow;decision|決定（名詞）|make a decision;probably|大概／可能|probably tomorrow;definitely|肯定地|definitely join;perhaps|或許|perhaps next week;in advance|提前|book in advance.`,[
['談下週計畫','What are you going to do next week?','I am going to visit a friend in Kaohsiung.','Have you booked your ticket?','Not yet. I will book it tonight.'],
['當下提供幫忙','I cannot carry all these boxes.','I will help you.','Thanks. Could you take the small one?','Sure. Where should I put it?'],
['確認承諾','Will you send me the details later?','Yes. I will send them after the meeting.','Do you think we need to book in advance?','Definitely. The place gets busy on weekends.']
],'分別說出已規劃的事、現在決定做的事和一項對別人的承諾。','I’ll 是 I will 的縮寫，尾音 l 輕輕收住即可。');
unit('邀請與協調','Invitations and arrangements','Would you like to …? / How about …?','How about 後接名詞或動名詞；拒絕邀請時可簡短說原因並提替代時間。',
`invite|邀請|invite a friend;invitation|邀請（名詞）|accept an invitation;join|加入|join us;accept|接受|accept the offer;decline|婉拒|decline politely;available time|有空時段|find an available time;make it|能到場|I cannot make it.;how about|……如何|How about Saturday?;shall we|我們……好嗎|Shall we meet?;sounds good|聽起來不錯|That sounds good.;another time|改天|Maybe another time.;unfortunately|不巧／不幸地|Unfortunately, I am busy.;something else|別的事物|try something else;pick up|接人／拿取|pick you up;drop off|送達|drop me off;meet up|碰面|meet up after work;hang out|一起消磨時間|hang out with friends;get together|聚在一起|get together on Sunday;occasion|場合／特別活動|a special occasion;celebrate|慶祝|celebrate a birthday.`,[
['邀約晚餐','Would you like to have dinner with us on Friday?','I would love to. What time?','How about seven at the noodle shop?','Sounds good. See you there.'],
['婉拒並提替代','Can you join us tomorrow?','Unfortunately, I already have plans.','No problem. Maybe another time.','How about meeting for coffee on Sunday?'],
['安排接送','Shall we meet at the station?','Could you pick me up at the north exit?','Sure. I can be there at six fifteen.','Thanks. I will message you when I arrive.']
],'邀請、拒絕、提替代方案各演練一次，確定最後形成具體約定。','Would you like to 可作為一個語塊練習，重點通常落在邀請的活動。');
unit('禮貌與社交場合','Social situations','Thank you for … / Would you mind …?','Thank you for 後可接名詞或動名詞。社交時可先表達感謝，再提出需要。',
`polite|有禮貌的|a polite request;respect|尊重|show respect;guest|客人|a dinner guest;host|主人／主辦者|thank the host;greeting|問候|a friendly greeting;introduce|介紹|introduce yourself;compliment|讚美|give a compliment;appreciate|感謝／欣賞|I appreciate your help.;grateful|感激的|I am grateful.;excuse me|不好意思／借過|Excuse me.;pardon|請再說一次|Pardon?;mind|介意|Would you mind?;permission|允許|ask permission;personal|私人的|a personal question;comfortable with|對……自在|comfortable with that;take your time|慢慢來|Take your time.;help yourself|請自便取用|Help yourself to some tea.;make yourself at home|別客氣／當自己家|Please make yourself at home.;not at all|一點也不／不客氣|Not at all.;my pleasure|樂意效勞|My pleasure.`,[
['到朋友家作客','Thank you for inviting me.','You are welcome. Please make yourself at home.','Your home is lovely.','Thanks. Help yourself to some tea.'],
['提出小請求','Would you mind if I opened the window?','Not at all. It is a little warm in here.','Thank you. Is this seat free?','Yes. Please sit down.'],
['回應私人問題','Can I ask you a personal question?','It depends on the question.','How much do you earn?','I would rather not discuss that, but we can talk about my work.']
],'練習作客、感謝與禮貌設定界線；不必為了聊天回答所有私人問題。','thank 的 th 和 thanks 的尾音 /ks/ 分開留意，保持自然清楚。');
unit('描述人物與個性','People and personality','She is someone who …','先說人物和關係，再用可觀察的行為支持形容，不只列出形容詞。',
`tall|高的|a tall person;short|矮的／短的|short hair;young|年輕的|a young teacher;older|年紀較大的|my older sister;friendly|友善的|a friendly neighbor;patient|有耐心的|a patient teacher;honest|誠實的|an honest answer;helpful|樂於助人的|a helpful coworker;creative|有創意的|a creative idea;careful|細心的|a careful driver;confident|有自信的|a confident speaker;shy|害羞的|a shy child;serious|認真的／嚴肅的|a serious person;outgoing|外向的|an outgoing friend;reliable|可靠的|a reliable teammate;neighbor|鄰居|my new neighbor;colleague|同事|a helpful colleague;appearance|外表|describe an appearance;personality|個性|a warm personality;sense of humor|幽默感|a good sense of humor.`,[
['介紹朋友','What is your friend Jo like?','She is patient and has a good sense of humor.','What makes you say she is patient?','She always explains things calmly when I ask questions.'],
['描述陌生會面對象','How will I recognize your colleague?','He is tall and wears a blue jacket.','Is he the person standing near the door?','Yes. That is him.'],
['談合作對象','Who do you enjoy working with?','My coworker Sam. He is reliable and careful.','Can you give me an example?','He checks the details and always finishes on time.']
],'介紹一位人物，加入一個外觀特徵、兩項個性與一個具體例子。','honest 的 h 不發音；an honest person 的 an 和 honest 可連在一起。');
unit('說明步驟與流程','Explaining a process','First … / Make sure … / Once …','說明流程時一次交代一個動作，並指出開始條件、關鍵檢查點與完成標準。',
`step|步驟|the first step;process|流程|a simple process;follow|遵循|follow the steps;instruction|指示|read the instructions;method|方法|a useful method;press|按壓|press the button;click|點擊|click the link;select|選取|select a file;enter|輸入／進入|enter your name;save|儲存|save your work;turn on|開啟電源|turn on the device;turn off|關閉電源|turn off the light;connect|連接|connect the cable;disconnect|中斷連接|disconnect the charger;make sure|確保|Make sure it is saved.;once|一旦|Once it is ready, start.;carefully|仔細地|read carefully;complete|完成|complete the form;result|結果|check the result;test|測試|test the connection.`,[
['說明基本操作','How do I save this document?','First, click the save button. Then choose a file name.','Do I need to select a folder?','Yes. Choose a folder you can find later.'],
['確認操作順序','Should I connect the cable before turning it on?','Yes. Make sure the cable is connected first.','What should I check next?','Once it is on, test the connection.'],
['教朋友做事','Could you show me how to use this app?','Sure. Open it and enter your name.','What happens after I complete the form?','You will see a confirmation message.']
],'教一位假想朋友完成你熟悉的三至五步驟流程，請他複述關鍵步驟。','first、next、finally 用短停頓分段，不要一口氣讀完所有指示。');
unit('曾經做過的事','Life experiences','Have you ever …? / I have never …','現在完成式可談沒有指定時間的經驗；追問確切時間時常改用過去式。',
`experience|經驗|a new experience;ever|曾經（問句）|Have you ever tried it?;never before|從未有過|never before;already|已經|I have already eaten.;yet|還／已經（否定或問句）|Not yet.;recently|最近|I recently started.;been|去過／曾是|I have been there.;done|做過了|I have done that.;seen|看過了|I have seen the film.;eaten|吃過了|I have eaten here.;tried|試過了|I have tried hiking.;learned|學會了|I have learned a lot.;visited before|以前拜訪過|I have visited before.;so far|到目前為止|so far this year;several|幾個／數個|several times;once or twice|一兩次|once or twice;first time|第一次|my first time;opportunity|機會|a good opportunity;recommend|推薦|recommend a place;worth|值得的|worth trying.`,[
['分享新體驗','Have you ever tried hiking at night?','No, I have not. Have you?','Yes. I tried it last month with a guide.','Was it worth trying?'],
['追問旅行經驗','Have you been to Tainan?','Yes. I have been there several times.','When did you last go?','I went there in May to visit a friend.'],
['談最近學習','Have you learned anything new recently?','I have started learning to cook.','What have you made so far?','I have made soup and a simple pasta dish.']
],'問三個 Have you ever 問題，對其中一個回答再追問時間、地點與感受。','have you 的 have 常輕讀；重點放在表示經驗的動詞。');
unit('表達意見與理由','Opinions and reasons','I think … because … / For example …','先說觀點，再補理由和例子。I think 後通常直接接完整子句。',
`opinion|意見|in my opinion;think|認為／思考|I think so.;believe|相信／認為|I believe it helps.;agree|同意|I agree with you.;disagree|不同意|I disagree politely.;point|論點／重點|a good point;view|看法|a different view;example|例子|give an example;evidence|證據|some evidence;benefit|好處|a clear benefit;drawback|缺點|one drawback;important|重要的|an important habit;useful|有用的|a useful tool;necessary|必要的|a necessary step;effective|有效的|an effective method;however|然而|However, it takes time.;although|雖然|Although it is hard, I enjoy it.;therefore|因此|therefore more useful;for instance|舉例來說|For instance, I walk to work.;in general|一般而言|In general, I prefer it.`,[
['分享學習看法','Do you think short daily practice is useful?','Yes, because it is easier to keep doing.','Can you give an example?','I practice for ten minutes before breakfast every day.'],
['談工作方式','What is one benefit of working from home?','I spend less time traveling.','Are there any drawbacks?','Yes. It can be harder to separate work from rest.'],
['回應不同觀點','I think a big city is the best place to live.','I see your point. However, I prefer a smaller town.','Why is that?','It is quieter, and I can walk to most places.']
],'用「觀點、理由、例子、邀請對方回應」的順序談一個日常議題。','because 後面稍微強調理由的關鍵字，讓聽者容易抓住重點。');
unit('比較與建議','Comparisons','This is … than … / It is the …','短形容詞常加 -er；較長形容詞常用 more。比較時要說清楚你重視的標準。',
`bigger|更大的|a bigger room;smaller|更小的|a smaller bag;faster|更快的|a faster train;slower|更慢的|a slower route;cheaper|更便宜的|a cheaper option;closer|更近的|closer to home;easier|更容易的|an easier method;harder|更困難的|a harder question;safer|更安全的|a safer place;best|最好的|the best choice;worst|最差的|the worst time;more expensive|更昂貴的|more expensive than this;less|更少|less noise;than|比|better than before;as good as|和……一樣好|as good as that one;quality|品質|good quality;value|價值|good value;compare|比較|compare two options;convenient|方便的|a convenient location;distance|距離|a short distance.`,[
['比較交通','Is the train faster than the bus?','Yes, but it is more expensive.','Which one is better for us?','The bus is fine if we have enough time.'],
['選住宿地點','This hotel is cheaper than the other one.','Is it as close to the station?','No. It is a little farther away.','I would pay more for a convenient location.'],
['給朋友建議','Which bag would you recommend?','The smaller one. It is easier to carry.','Is the quality good?','Yes. I think it is the best value for your needs.']
],'比較兩個你熟悉的選項，用價格、方便性、品質三個標準給建議。','than 通常輕讀，形容詞比較級才是句中的重點。');
unit('解決問題與取捨','Solving problems','The problem is … / One option is …','先定義問題和限制，再提出至少兩個可行選項，最後說明選擇理由。',
`challenge|挑戰|a new challenge;cause|原因／造成|the main cause;effect|影響／效果|a positive effect;option available|可用選項|an option available today;alternative|替代方案|another alternative;consider|考慮|consider the cost;suggest|建議|suggest a solution;suggestion|建議（名詞）|a useful suggestion;improve|改善|improve the process;reduce|減少|reduce the cost;increase|增加|increase the time;avoid|避免|avoid mistakes;prevent|預防|prevent a problem;limit|限制|a time limit;priority|優先事項|our first priority;trade-off|取捨|a difficult trade-off;depend on|取決於|depend on the weather;deal with|處理|deal with the issue;figure out|弄清楚|figure out the cause;work out|解決／進展順利|work out a plan.`,[
['找出問題','What is causing the delay?','We are waiting for one missing file.','Could we start with the files we already have?','Yes. That would help us save time.'],
['比較解法','We need a quieter place for the meeting.','One option is to book a small room.','What is the alternative?','We could meet online, but the connection may be unstable.'],
['做出取捨','Should we choose the cheaper service?','It depends on our priority.','We need reliable support more than the lowest price.','Then the second option may be better.']
],'提出一個真實的小問題、兩個解法與各自代價，再選一個方案。','problem 的重音在前面；不要為每一個音節加上相同重音。');
unit('日常科技與網站','Everyday technology','It keeps … / Could you check …?','描述科技問題時，說明裝置、剛做的動作與看見的狀況，避免只說 It is broken。',
`device|裝置|a mobile device;screen|螢幕|a bright screen;battery|電池|a low battery;charger|充電器|a phone charger;cable|線材|a charging cable;connection|連線|a stable connection;internet|網際網路|use the internet;website|網站|open a website;browser|瀏覽器|update the browser;password|密碼|change a password;account|帳號|a personal account;sign in|登入|sign in to your account;sign out|登出|sign out safely;download|下載|download a file;upload|上傳|upload a photo;backup|備份|make a backup;restart|重新啟動|restart the device;setting|設定|change the settings;notification|通知|turn off notifications;privacy|隱私|protect your privacy.`,[
['描述問題','My phone battery runs out very quickly.','When did you first notice that?','It started after the last update.','Let us check the battery settings first.'],
['網站操作','I cannot sign in to the website.','Do you see an error message?','Yes. It says the password is incorrect.','Please use the password reset option.'],
['解釋備份','Should I back up my photos before changing phones?','Yes. Make a backup and check that the files are there.','Can I use the same account on the new phone?','Usually, yes. Make sure you can sign in first.']
],'向朋友描述一個裝置或網站問題，依序說明症狀、時間與已嘗試的方法。','website 的 t 與下一個字連接時可能不明顯；注意 web 和 site 的重音。');
unit('線上合作與工作協調','Working together online','Could you clarify …? / I will take care of …','會議中先確認共同目標，再把每個任務的負責人與期限說清楚。',
`remote|遠端的|remote work;online|在線上的|an online meeting;offline|離線的|work offline;screen sharing|螢幕分享|start screen sharing;microphone|麥克風|mute the microphone;mute|靜音|Please mute your microphone.;unmute|解除靜音|unmute yourself;agenda|議程|the meeting agenda;deadline|截止時間|meet the deadline;progress|進度|check our progress;feedback|回饋|give feedback;draft|草稿|the first draft;review|檢視／審查|review the draft;approve|核准|approve the change;clarify|釐清|clarify the request;assign|指派|assign a task;take care of|處理／負責|take care of the file;follow up|後續追蹤|follow up tomorrow;time zone|時區|a different time zone;technical issue|技術問題|a technical issue.`,[
['線上會議開場','Can everyone hear me?','Yes, but we cannot see your screen.','Let me start screen sharing. Is it visible now?','Yes. Please go ahead.'],
['確認負責事項','Who will review the first draft?','I will take care of that.','Could you send your feedback by Thursday?','Yes. I will leave comments in the document.'],
['釐清不明需求','Could you clarify what you mean by a simpler design?','I would like fewer steps on the first page.','So the main priority is easier navigation?','Exactly. We can discuss the colors later.']
],'模擬五分鐘工作會議：確認目標、分工、期限，最後口頭摘要。','feedback 是不可數名詞；練習 give feedback，而不是硬加複數。');
unit('日常消息與資訊來源','Talking about news','I heard that … / According to …','分享消息時分清楚親身經歷、他人轉述與尚未確認的內容。用來源和不確定語氣讓意思準確。',
`news|新聞／消息|some good news;headline|標題|read a headline;article|文章|a short article;report|報導|a local report;source|來源|a reliable source;according to|根據|according to the report;apparently|據說／看來|Apparently, it is popular.;seem|似乎|It seems useful.;claim|聲稱／主張|a strong claim;fact|事實|check the facts;rumor|傳聞|an unconfirmed rumor;reliable source|可靠來源|find a reliable source;confirm information|確認資訊|confirm information first;recent|最近的|a recent article;current|目前的|the current situation;change|變化|a big change;community|社區／群體|the local community;public|公眾的|a public event;announcement|公告|an official announcement;share a link|分享連結|Can you share a link?`,[
['分享地方消息','I heard that a new library is opening near the station.','Where did you hear that?','I read an announcement on the city website.','That sounds useful. When does it open?'],
['保留不確定性','Apparently, the cafe is closing next month.','Has that been confirmed?','I am not sure. A friend mentioned it.','Let us check before we change our plans.'],
['延伸新聞聊天','Have you read anything interesting recently?','I read an article about people working fewer hours.','What was the main point?','It discussed how rest can affect the quality of work.']
],'用一則不涉及爭議的生活消息練習摘要、交代來源與表達不確定性。','according to 的重音通常在 according；來源名稱可清楚放慢。');
unit('文化與生活差異','Culture and everyday customs','In my experience … / Is it common to …?','談文化時避免把個人經驗說成所有人的規則。可用 often、in my experience 和 it depends。',
`culture|文化|learn about a culture;custom|習俗|a local custom;tradition|傳統|a family tradition;festival|節慶|a spring festival;celebration|慶祝活動|a family celebration;habit|習慣|a daily habit;common|常見的|a common habit;unusual|不常見的|an unusual custom;similar|相似的|a similar routine;difference|差異|a small difference;respectful|尊重人的|a respectful question;greet|問候|greet a guest;bow|鞠躬|bow politely;shake hands|握手|shake hands when meeting;take off|脫下|take off your shoes;gift|禮物|bring a small gift;typical|典型的|a typical breakfast;in my experience|依我的經驗|In my experience, it varies.;it varies|各有不同|It varies by family.;get used to|習慣於|get used to a new routine.`,[
['詢問作客習慣','Should I take off my shoes before coming in?','Yes, please. We usually do that at home.','Thanks for letting me know.','No problem. There are slippers by the door.'],
['比較早餐','What do people usually eat for breakfast where you live?','It varies, but I often have bread and eggs.','I usually have rice or noodles.','That sounds good. I would like to try it.'],
['分享節慶','Do you have a favorite family tradition?','We get together for dinner during the New Year holiday.','What do you enjoy most about it?','Having time to talk with everyone.']
],'比較兩種生活習慣，提出尊重的問題，並用個人經驗而非刻板印象回應。','culture 的尾音不是每個字母分開念；先模仿整句中的節奏。');
unit('感受、支持與同理','Empathy and support','That sounds … / Would you like to …?','同理回應可先承認感受，再詢問對方需要傾聽、協助或空間，不急著下建議。',
`happy|開心的|happy to hear that;sad|難過的|feel sad;worried|擔心的|worried about work;frustrated|挫折的|feel frustrated;disappointed|失望的|a little disappointed;relieved|鬆一口氣的|feel relieved;proud|感到驕傲的|proud of your progress;lonely|孤單的|feel lonely;calm|平靜的|stay calm;upset|不高興／難過的|feel upset;supportive|支持人的|a supportive friend;encourage|鼓勵|encourage someone;comfort|安慰|offer comfort;listen to|傾聽|listen to a friend;take a break|休息一下|take a short break;talk about|談論|talk about it;go through|經歷困難|go through a hard time;that sounds tough|聽起來很不容易|That sounds tough.;here for you|願意支持你|I am here for you.;no pressure|沒有壓力／不勉強|No pressure to answer.`,[
['傾聽朋友','I am frustrated with work this week.','That sounds tough. Do you want to talk about it?','I keep getting new tasks before finishing the old ones.','Would it help to discuss your priorities with your manager?'],
['慶祝進步','I finally gave a short presentation in English.','That is great. You must feel proud.','I was nervous, but people understood me.','You have worked hard. I am happy for you.'],
['尊重空間','You seem a little quiet today. Are you okay?','I am upset, but I do not want to talk yet.','That is okay. No pressure. I am here if you need me.','Thank you. I appreciate that.']
],'練習傾聽、慶祝和尊重界線三種回應，每次先回應感受再追問。','frustrated、relieved 的語調可帶出感受，但不用模仿誇張戲劇式語氣。');
unit('不同意也能好好聊','Polite disagreement','I see what you mean, but …','先確認你理解對方的理由，再說不同看法；針對觀點討論，避免把人貼標籤。',
`perspective|角度／觀點|a different perspective;fair|公平的／合理的|a fair point;valid|有道理的|a valid concern;concern|顧慮|a common concern;assumption|假設|check an assumption;respectfully|尊重地|disagree respectfully;partly|部分地|I partly agree.;completely|完全地|completely different;on the other hand|另一方面|On the other hand, it costs more.;to some extent|某種程度上|I agree to some extent.;not necessarily|不一定|Not necessarily.;that depends|那要看情況|That depends.;compromise|折衷|find a compromise;common ground|共同點|find common ground;balanced|平衡的|a balanced view;reasonable|合理的|a reasonable suggestion;convince|說服|convince the team;argue|爭論／主張|argue a point;misunderstanding|誤會|clear up a misunderstanding;in that case|那樣的話|In that case, I agree.`,[
['不同生活選擇','Everyone should live in a big city.','I see why you like cities, but that may not work for everyone.','What do you mean?','Some people prefer quiet places or need to be near family.'],
['尋找折衷','I think we should meet in person every day.','I partly agree. Meeting in person helps, but travel takes time.','What would you suggest?','Perhaps two office days and three remote days.'],
['修正誤解','You said the plan was impossible.','I am sorry. That is not what I meant.','Could you explain your concern?','I think it is possible, but we need more time.']
],'選一個日常偏好，提出不同看法，承認對方一點優點，再找折衷方案。','I see what you mean 可以平穩連讀；在 but 後清楚說出真正不同的地方。');
unit('說一段完整故事','Longer storytelling','I was … when … / Looking back …','用過去進行式交代當時背景，再用過去式說主要事件。結尾說這件事帶來的理解。',
`background|背景|the background of the story;setting|故事場景|a familiar setting;character|人物|the main character;beginning|開頭|at the beginning;middle|中段|in the middle;ending|結尾|a clear ending;unexpected|意外的|an unexpected change;turning point|轉捩點|the turning point;realized|意識到了|I realized the problem.;noticed|注意到了|I noticed a sign.;managed|成功設法|I managed to finish.;eventually|最終|We eventually arrived.;meanwhile|同時|Meanwhile, Sam called.;afterwards|之後|We talked afterwards.;looking back|回頭看|Looking back, I learned a lot.;at first|起初|At first, I was worried.;in the end|最後|In the end, it worked.;learn a lesson|學到教訓|learn a useful lesson;by chance|碰巧|meet by chance;all of a sudden|突然間|All of a sudden, it stopped.`,[
['故事開場','Can you tell me about a memorable trip?','I was traveling alone when I missed my train.','How did that happen?','I was waiting on the wrong platform.'],
['轉折與解決','What did you do after missing the train?','At first, I was worried. Then I asked a staff member for help.','Were you able to continue your trip?','Yes. I eventually got on another train.'],
['回顧與延伸','What did you learn from that experience?','I learned to check the platform early and ask questions.','Would you travel alone again?','Definitely. Looking back, it helped me become more confident.']
],'說一段三分鐘故事，包含背景、主要事件、轉折、結果與反思，回聽後刪掉不必要的細節。','講故事時用停頓區分背景和事件；不是每個單字都要同樣大聲。');
unit('假設與可能性','Hypothetical situations','If I had …, I would …','假設現在不一定真實的情況，可用 If + 過去式，主句 would + 原形。先理解情境，再記句型。',
`if|如果|if I had time;would choose|會選擇|I would choose this.;could be|可能是|It could be useful.;imagine|想像|imagine a new city;suppose|假設|Suppose you had a week off.;possibility|可能性|another possibility;likely|可能的|a likely result;unlikely|不太可能的|an unlikely event;maybe|也許|Maybe next time.;what if|如果……會怎樣|What if it rains?;in case|以防|bring it in case;unless|除非|unless it rains;otherwise|否則|Otherwise, we will be late.;risk|風險|a small risk;chance|機會／可能性|a good chance;impossible|不可能的|almost impossible;realistic|實際的|a realistic plan;imagination|想像力|use your imagination;dream|夢想|a personal dream;unlimited|無限制的|unlimited time.`,[
['假設有假期','If you had a month off, what would you do?','I would travel slowly and spend more time in small towns.','Would you travel alone?','Maybe. I would also like to visit friends.'],
['準備替代計畫','What if it rains during our picnic?','We could eat at my place instead.','Should we decide now?','Let us check the weather tomorrow.'],
['談理想選擇','If money were not a problem, where would you live?','I would choose a place near the sea.','What would you miss about your current home?','My friends and the convenient public transport.']
],'回答三個假設問題，每次加入原因與一個可能的缺點。','would 常輕讀；if 子句後停一下，讓假設和結果容易區分。');
unit('澄清、換句話說與修復','Clarifying meaning','Do you mean …? / What I mean is …','聽不懂可請求例子；說不出可描述用途或特徵。修復溝通比假裝聽懂更實用。',
`clarification|釐清|ask for clarification;rephrase|換句話說|Could you rephrase that?;phrase|片語／措辭|a useful phrase;expression|表達方式|a common expression;meaning|意思|the meaning of a word;definition|定義|a simple definition;context|上下文|understand the context;specific|具體的|a specific example;exactly|確切地|What exactly do you mean?;roughly|大約地|roughly ten minutes;in other words|換句話說|In other words, we need more time.;what I mean is|我的意思是|What I mean is this.;do you mean|你是指……嗎|Do you mean tomorrow?;let me put it differently|讓我換個說法|Let me put it differently.;not quite|不完全是|Not quite.;more or less|差不多|More or less.;something like|類似……|something like a small box;the thing that|那個用來……的東西|the thing that holds your phone;misheard|聽錯了|I misheard the time.;make sense|有道理／可理解|Does that make sense?`,[
['確認對方意思','We need a more flexible schedule.','Do you mean we can choose our starting time?','Yes, as long as the main tasks are covered.','That makes sense.'],
['換句話說','I need the thing that holds the phone in a car.','Do you mean a phone holder?','Exactly. I could not remember the word.','No problem. I knew what you meant.'],
['修復聽錯資訊','I thought you said fifteen, not fifty.','Sorry. I meant fifty dollars.','Thanks for clarifying. That changes my decision.','Would you like to look at a cheaper option?']
],'刻意不用三個熟悉的名詞，改用特徵與用途描述，讓假想對方猜出意思。','fifteen 與 fifty 的重音和尾音都不同；用完整金額再次確認。');
unit('延伸與轉換話題','Keeping a conversation going','You mentioned … / Speaking of …','先回應上一句的內容，再提出相關追問。換話題前用簡短連結，避免連續盤問。',
`mention|提到|You mentioned your trip.;curious|好奇的|I am curious.;wonder|想知道|I wonder what it is like.;speaking of|說到……|Speaking of food, are you hungry?;by the way|順帶一提|By the way, how was your trip?;anyway|總之／回到正題|Anyway, what happened next?;as I was saying|如我剛才所說|As I was saying, it was busy.;go on|繼續說|Please go on.;tell me more|多說一點|Tell me more about it.;how come|怎麼會／為什麼|How come you chose that?;what was that like|那是什麼樣的體驗|What was that like?;follow-up question|追問|ask a follow-up question;topic|話題|a new topic;conversation|對話|a friendly conversation;connection between|……之間的關聯|a connection between the topics;interesting point|有趣的觀點|That is an interesting point.;come to think of it|這麼一想|Come to think of it, I agree.;that reminds me|那讓我想到|That reminds me of my trip.;keep going|繼續|Keep going.;back to|回到……|back to your question.`,[
['從興趣延伸','You mentioned that you started cooking. What was that like?','Difficult at first, but I enjoy trying simple dishes.','What is one dish you would recommend for a beginner?','Soup. You can start with a few ingredients.'],
['自然換話題','The coffee here is really good.','Yes. Speaking of coffee, did you try that new cafe?','Not yet. Is it worth visiting?','I think so. It is quiet and close to the park.'],
['回到原來話題','By the way, how was your trip?','Great. I can tell you later. You were talking about your new job.','Right. As I was saying, the team has been very helpful.','What do you like most about working with them?']
],'維持五分鐘聊天，每次回應包含一個反應、一點自己的資訊和一個相關追問。','Tell me more 可輕鬆說，不必每個追問都用考試式的上揚語調。');
unit('認識新朋友與人脈','Meeting new people','How did you get into …?','社交對話可以從共同場合開始，逐步聊興趣、工作或經驗，並留意對方願不願意深入。',
`background in|……方面的背景|a background in design;field|領域|in this field;industry|產業|the service industry;role|角色／職責|my current role;career|職涯|a career change;skill|技能|a useful skill;strength|優勢|my main strength;interest in|對……的興趣|an interest in languages;get into|開始投入|get into cooking;inspired|受到啟發的|inspired by a friend;recommendation|推薦（名詞）|a personal recommendation;network|人脈／網路|build a network;stay in touch|保持聯絡|Let us stay in touch.;nice talking to you|很高興和你聊天|It was nice talking to you.;catch up|敘舊／跟上|catch up soon;introduce someone|介紹某人|introduce someone to a friend;shared interest|共同興趣|a shared interest in music;mutual friend|共同朋友|a mutual friend;local event|地方活動|meet at a local event;look forward to|期待|look forward to meeting again.`,[
['從場合開聊','Is this your first time at this event?','Yes. A friend recommended it.','What brought you here?','I wanted to meet people who are interested in design.'],
['談投入經過','How did you get into website design?','I started by making a small site for a friend.','What do you enjoy most about it?','Turning a confusing idea into something people can use.'],
['自然結束聊天','It was nice talking to you.','You too. I enjoyed hearing about your work.','Would you like to stay in touch?','Sure. Let us exchange contact details.']
],'演練認識新朋友的開場、兩次追問和自然結尾，不把對話變成自我推銷。','nice talking to you 比逐字分開更像自然道別；練習先重讀 nice 和 talking。');
unit('目標與學習反思','Goals and reflection','I have improved … / My next step is …','描述進步時給具體證據，區分已做到、仍在練習和下一步，不只說 My English is bad。',
`reflection|反思|a learning reflection;achievement|成就|a small achievement;improvement|進步|a clear improvement;fluency|流暢度|improve fluency;accuracy|準確度|practice accuracy;confidence|信心|build confidence;consistency|持續性|consistency matters;motivation|動機|find motivation;effort|努力|make an effort;habit building|習慣建立|habit building takes time;measure|衡量|measure progress;track|追蹤|track your practice;review again|再次複習|review again tomorrow;set a goal|設定目標|set a realistic goal;achievable|可達成的|an achievable goal;challenge yourself|挑戰自己|challenge yourself gently;keep practicing|持續練習|Keep practicing.;make progress|取得進步|make steady progress;next step|下一步|my next step;long-term|長期的|a long-term plan.`,[
['描述進步','How has your English changed this year?','I can now describe my work and ask follow-up questions.','What helped you most?','Regular listening and speaking practice.'],
['面對困難','What is still challenging for you?','I sometimes lose track when people speak quickly.','What could you try next?','I could listen to short conversations and summarize them.'],
['設定下一步','What is your next learning goal?','I want to have a ten-minute conversation without relying on notes.','How will you work toward it?','I will practice twice a week and review my recordings.']
],'回聽早期錄音或重做第一週任務，用英文指出三項變化與一項下一步。','fluency 的意思是流暢度；說得清楚、有停頓也可以是有效溝通。');
unit('延伸聊天實戰','Longer conversations','Let me think … / What about your experience?','自然聊天允許停頓。用短暫思考語、改述和追問維持互動，不必每句都很複雜。',
`let me think|讓我想一下|Let me think for a moment.;to be honest|老實說|To be honest, I am not sure.;as far as I know|據我所知|As far as I know, it is open.;personally|就我個人而言|Personally, I prefer quiet places.;especially|尤其|especially on weekends;actually|其實|Actually, I changed my mind.;at the moment|目前|at the moment;these days|最近這陣子|These days, I cook more.;a while|一段時間|for a while;once in a while|偶爾|once in a while;in particular|特別是|one place in particular;from time to time|不時|from time to time;as well|也|I enjoy it as well.;not really|不太／不完全是|Not really.;more importantly|更重要的是|More importantly, it is useful.;in fact|事實上|In fact, I have tried it.;overall|整體而言|Overall, it was a good trip.;sort of|有點／某種程度上|sort of difficult;in a way|某方面來說|In a way, it helped.;how about yourself|你自己呢|How about yourself?`,[
['近況聊起','What have you been doing these days?','I have been spending more time cooking at home.','Is that something you have always enjoyed?','Not really. I started recently because I wanted to try something new.'],
['表達需要思考','What is the best advice you have ever received?','Let me think. Probably to start before I feel completely ready.','How has that helped you?','It helped me practice English without waiting to be perfect.'],
['把話題交還對方','Overall, I enjoyed living in a smaller town.','What did you like most about it?','The slower pace. How about your experience?','I liked it too, although I missed the public transport in the city.']
],'不用筆記聊八分鐘，至少連接三個相關話題；卡住時使用改述或澄清，不回到中文草稿。','Let me think 後自然停頓是正常現象，不需用很快的填充語掩蓋思考。');
unit('年度生活對話整合','Putting it all together','Respond → add detail → ask back','整合介紹、經驗、觀點、問題處理和追問。以對方能理解並願意繼續聊為目標，而非背完固定稿。',
`small talk|輕鬆閒聊|make small talk;in common|共同的|have something in common;make a connection|建立連結|make a connection;give it a try|試試看|Give it a try.;step by step|一步一步|learn step by step;on my own|靠自己|practice on my own;at my own pace|照自己的步調|learn at my own pace;get the hang of|掌握訣竅|get the hang of it;come up with|想出|come up with an idea;bring up|提起話題|bring up a topic;work towards|朝……努力|work towards a goal;make the most of|充分利用|make the most of your time;look back on|回顧|look back on the year;keep in mind|記住／留意|keep this in mind;be willing to|願意|be willing to ask;open to|願意接受|open to new ideas;keep up with|跟上|keep up with a conversation;get across|傳達清楚|get your meaning across;take it further|再深入一步|take the conversation further;keep in touch|保持聯繫|keep in touch with friends.`,[
['生活與工作整合','Tell me a little about yourself and what you do.','I live in Taiwan and work with customers. I also enjoy learning languages.','What do you find interesting about your work?','I like solving practical problems and meeting different people.'],
['經驗與觀點整合','What is one experience that changed your perspective?','Learning English taught me to ask questions even when I am unsure.','Why was that important to you?','It helped me connect with people instead of worrying about every mistake.'],
['未來與延伸整合','What would you like to try next year?','I would like to travel and use English more often.','What would help you get ready?','More listening practice and regular conversations with different people.']
],'完成十分鐘整合對話：介紹、生活、工作、經驗、觀點與未來，最後自然結束並自我檢核。','錄音時檢查關鍵字、停頓與回應是否清楚；不以模仿某種口音作為唯一標準。');
const EARLY_TRANSLATIONS=[
[['你好，我叫 Alex。','嗨 Alex，我是 Sam。','很高興認識你，Sam。','我也很高興認識你。'],['你是 Sam 嗎？','是的，我是。你是 Alex 嗎？','是的。我是新來的。','歡迎你，Alex。'],['Sam，這是我的朋友 Jo。','你好 Jo，很高興認識你。','嗨 Sam，我也很高興認識你。','請坐這裡。']],
[['你來自哪裡？','我來自台灣。你呢？','我來自加拿大。你住在台北嗎？','是的，我現在住在台北。'],['你會說英語嗎？','一點點。我也會說中文。','太好了。我會一點中文。','我們可以一起練習。'],['你住在哪裡？','我住在台北附近，那是個大城市。','你的朋友也來自台灣嗎？','不是，她來自日本。']],
[['會來幾個人？','三個人。我們有四張椅子嗎？','有，我們有四張椅子。','很好，我們還需要一個杯子。'],['你的名字怎麼拼？','S、A、M。','可以慢慢地再說一次嗎？','當然，S、A、M。'],['你的電話號碼是多少？','是零九、一二、三四。','零九、一二、三四，正確嗎？','是的，正確。']],
[['她是你的老師嗎？','不是，她是我的朋友。','她是學生嗎？','是的，我們一起學英語。'],['他們準備好了嗎？','他們還沒準備好。','你準備好了嗎？','是的，我現在準備好了。'],['那些人是誰？','他們是我的朋友。','他們親切嗎？','是的，他們很親切。']],
[['你早上都做什麼？','我吃早餐然後去工作。','你喝咖啡嗎？','是的，我在早餐後喝。'],['你幾點下班？','我通常六點下班。','你下班後回家嗎？','是的，我在家煮晚餐。'],['你會早睡嗎？','不會，我通常晚睡。','你睡前會讀書嗎？','會，我學十分鐘英語。']]
];
const YEAR_WORD_MAP=new Map();
const hashTerm=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return(h>>>0).toString(16)};
YEAR_UNITS.forEach((u,i)=>{u.week=i+1;u.vocab=u.vocab.map(w=>{const key=w.en.toLowerCase()+'|'+w.zh;let stored=YEAR_WORD_MAP.get(key);if(!stored){stored={...w,id:'y2-'+hashTerm(key),theme:i,week:i+1};YEAR_WORD_MAP.set(key,stored);}return stored});u.scenes.forEach((s,j)=>{s.zh=EARLY_TRANSLATIONS[i]?.[j]||null;s.audio=s.lines.join(' ');});});
const YEAR_WORDS=[...YEAR_WORD_MAP.values()];
const ALL_WORDS=[...WORDS,...YEAR_WORDS]; // old card IDs remain valid after the upgrade
const DAY_SKILLS=['建立詞語與聽懂情境','跟讀並替換個人資訊','聽力與主動回想','角色互換與句型練習','新情境與延伸追問','整合口說與英文思考','每週檢核與補強'];
const PHASES=[{title:'從零開始，完成日常互動',range:'Day 1–91',goal:'介紹自己、生活習慣、點餐與購物',start:1,end:91},{title:'談生活、工作與過去經驗',range:'Day 92–182',goal:'處理日常需求，說一段有順序的故事',start:92,end:182},{title:'延伸表達，說明理由與解決問題',range:'Day 183–273',goal:'旅行、工作流程、比較與意見交流',start:183,end:273},{title:'維持對話，分享觀點與感受',range:'Day 274–365',goal:'追問、澄清、文化交流與長時間聊天',start:274,end:365}];
const STAGE_DAYS=[30,60,90,120,150,180,210,240,270,300,330,365];
function getLesson(day){
 day=Math.max(1,Math.min(365,Number(day)||1));const index=Math.min(51,Math.floor((day-1)/7)),u=YEAR_UNITS[index],cycle=day===365?6:(day-1)%7,sceneIndex=Math.min(2,Math.floor(cycle/2)),scene=u.scenes[sceneIndex];
 const words=cycle<4?u.vocab.slice(cycle*5,cycle*5+5):u.vocab.filter((_,i)=>(i+cycle)%4===0).slice(0,5);
 const phase=PHASES.findIndex(p=>day>=p.start&&day<=p.end),assessment=day===365?'年度整合檢核':STAGE_DAYS.includes(day)?'階段檢核':cycle===6?'每週檢核':null;
 const skills=day===365?'年度整合與下一步':DAY_SKILLS[cycle];
 return {day,week:index+1,unit:u,phase,cycle,scene,sceneIndex,words,newWordCount:cycle<4&&day!==365?5:0,assessment,focus:skills,title:day===365?'年度整合挑戰':cycle===6?`${u.title} · 每週檢核`:`${scene.title} · ${skills}`,dialogue:scene.lines,pattern:u.pattern,grammar:u.grammar,prompt:u.mission,sound:u.sound,t:[u.en,u.title,['🌱','🌿','🧭','🌏'][phase],'',scene.lines[0],scene.lines[1],'',u.pattern,u.mission]};
}
const ANNUAL_COURSE=Array.from({length:365},(_,i)=>getLesson(i+1));
const COURSE_STATS={days:365,weeks:YEAR_UNITS.length,wordEntries:YEAR_UNITS.reduce((n,u)=>n+u.vocab.length,0),uniqueTerms:new Set(YEAR_WORDS.map(w=>w.en.toLowerCase())).size,dialogues:YEAR_UNITS.reduce((n,u)=>n+u.scenes.length,0),weeklyChecks:52,stageChecks:12};
